using System.Text.RegularExpressions; using InovaGed.Environment.Doctor.Quality;
namespace InovaGed.Environment.Doctor.Checks;
public sealed class RazorQualityCheck : IQualityCheck { public string Name=>"Razor";
 public Task<IReadOnlyList<QualityFinding>> RunAsync(QualityContext c,CancellationToken ct){var r=new List<QualityFinding>(); foreach(var f in Directory.EnumerateFiles(Path.Combine(c.Root,"InovaGed.Web"),"*.cshtml",SearchOption.AllDirectories)){var s=File.ReadAllText(f); var rel=Path.GetRelativePath(c.Root,f); foreach(var line in s.Replace("\r","").Split('\n').Select((v,i)=>(v,n:i+1))){if(Regex.IsMatch(line.v,@"^\s*@model\s+\S+\s+\S")) r.Add(Bad(rel,line.n,"@model deve ficar sozinho na linha.")); if(Regex.IsMatch(line.v,@"\?\?\s*\[\s*\]")) r.Add(Bad(rel,line.n,"uso de ?? [] não suportado em RuntimeCompilation; use Array.Empty<T>() ou new List<T>().")); if(Regex.IsMatch(line.v,@"ViewDataDictionary\s*\(\s*ViewData\s*\).*\{\s*\{\s*[""']Title[""']"))r.Add(Bad(rel,line.n,"Não usar Title em partial ViewData. Use AlertTitle, HeroTitle, CardTitle ou TableTitle.")); if(Regex.IsMatch(line.v,@"@foreach\s*\([^\r\n]*new\s*\[\]"))r.Add(Bad(rel,line.n,"Crie lista tipada dentro de bloco @{ } antes do foreach.")); if(Regex.IsMatch(line.v,@"<button\b(?=[^>]*(?:asp-action|class)=)(?![^>]*\btype\s*=)[^>]*>" ,RegexOptions.IgnoreCase))r.Add(Bad(rel,line.n,"Todo botão deve ter type explícito; use formaction/formmethod para actions diferentes."));} foreach(Match style in Regex.Matches(s,@"<style\b[^>]*>(.*?)</style>",RegexOptions.Singleline|RegexOptions.IgnoreCase)) foreach(var token in new[]{"media","page","keyframes","supports"}) if(Regex.IsMatch(style.Groups[1].Value,$@"(?<!@)@{token}\b")) r.Add(Bad(rel,1,$"@{token} dentro de <style> deve ser @@{token}; prefira CSS externo.")); foreach(Match form in Regex.Matches(s,@"<form\b.*?</form>",RegexOptions.Singleline|RegexOptions.IgnoreCase)){var fields=Regex.Matches(form.Value,@"<(?:input|select|textarea)\b[^>]*asp-for\s*=\s*[""']([^""']+)",RegexOptions.IgnoreCase).Select(x=>x.Groups[1].Value);foreach(var duplicate in fields.GroupBy(x=>x,StringComparer.OrdinalIgnoreCase).Where(x=>x.Count()>1))r.Add(Bad(rel,1,$"Campo asp-for '{duplicate.Key}' duplicado no mesmo form; use um campo canônico."));}} if(r.Count==0)r.Add(new(Name,QualityStatus.Pass,"Views Razor não contêm padrões incompatíveis conhecidos.")); return Task.FromResult<IReadOnlyList<QualityFinding>>(r);}
 private QualityFinding Bad(string f,int line,string m)=>new(Name,QualityStatus.Fail,$"{f}:{line}: {m}","A RuntimeCompilation pode falhar.","Corrigir a sintaxe Razor antes do deploy.",Resource:f);
}
